unitsize(1 cm);

pair[] O;
real[] r;

r[1] = 4 - 2*sqrt(2);
O[1] = (r[1],r[1]);
r[2] = 4 + 2*sqrt(2);
O[2] = (r[2],r[2]);

draw(Circle(O[1],r[1]));
draw(arc(O[2],r[2],160,290));
draw(Circle((3,0),1));
draw((-0.5,0)--(9,0));
draw((0,-0.5)--(0,9));
draw(O[1]--(r[1],0));
draw(O[1]--(0,r[1]));
draw(O[1]--(3,0));
draw(O[2]--(r[2],0));
draw(O[2]--(0,r[2]));
draw(O[2]--(3,0));

dot("$(3,0)$", (3,0), S);
dot("$O_1$", O[1], N);
dot("$O_2$", O[2], NE);
